// import-chapters.js  —  run: node import-chapters.js
// Scrapes Desire of Ages ch 3-87 from egwwritings.org and uploads to Firebase

const FIREBASE_PROJECT = 'desire-of-ages-treasury';
const API_KEY          = 'AIzaSyCZMh4KUoXtSgCP3xCQ7atA8cJ7CQOGgfU';
const FS_BASE = `https://firestore.googleapis.com/v1/projects/${FIREBASE_PROJECT}/databases/(default)/documents`;

const DELAY_MS = 1200; // be polite to the server

// ── Helpers ──────────────────────────────────────────────────────────────────

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

// Convert plain JS value → Firestore REST document value
function fsVal(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === 'boolean')        return { booleanValue: v };
  if (typeof v === 'number')
    return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (typeof v === 'string')         return { stringValue: v };
  if (Array.isArray(v))              return { arrayValue: { values: v.map(fsVal) } };
  if (typeof v === 'object')
    return { mapValue: { fields: Object.fromEntries(Object.entries(v).map(([k,x]) => [k, fsVal(x)])) } };
  return { stringValue: String(v) };
}
function fsDoc(obj) {
  return { fields: Object.fromEntries(Object.entries(obj).map(([k,v]) => [k, fsVal(v)])) };
}

// HTTP fetch with browser-like headers
async function get(url) {
  const res = await fetch(url, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
      'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      'Accept-Language': 'en-US,en;q=0.9',
    }
  });
  if (!res.ok) throw new Error(`HTTP ${res.status} — ${url}`);
  return res.text();
}

// Strip HTML tags and decode basic entities
function stripHtml(s) {
  return s
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s{2,}/g, ' ')
    .trim();
}

// Extract readable paragraphs from egwwritings HTML
function extractParagraphs(html) {
  const paras = [];
  // egwwritings uses <p class="...para..."> for body text
  const re = /<p[^>]*class="[^"]*para[^"]*"[^>]*>([\s\S]*?)<\/p>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const text = stripHtml(m[1]);
    if (text.length > 40) paras.push(text);
  }
  // Fallback: grab all <p> with reasonable length
  if (paras.length < 3) {
    const re2 = /<p[^>]*>([\s\S]*?)<\/p>/gi;
    while ((m = re2.exec(html)) !== null) {
      const text = stripHtml(m[1]);
      if (text.length > 60 && !paras.includes(text)) paras.push(text);
    }
  }
  return paras;
}

// Parse TOC page → map of chapterNumber → URL path
function parseTOC(html) {
  const map = {};
  // Links like href="/en/book/130.89" with text "Chapter 3" or similar
  const re = /href="(\/en\/book\/130\.\d+)"[^>]*>[\s\S]*?Chapter\s+(\d+)/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    map[parseInt(m[2], 10)] = 'https://m.egwwritings.org' + m[1];
  }
  // Also try links where title contains chapter text nearby
  if (Object.keys(map).length < 5) {
    const re2 = /href="(\/en\/book\/130\.(\d+))"/gi;
    // collect all book links; we'll try them sequentially if TOC parsing fails
  }
  return map;
}

// Upload one chapter's data to Firestore
async function upload(chId, data) {
  const url = `${FS_BASE}/chExtras/${chId}?key=${API_KEY}`;
  const res = await fetch(url, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(fsDoc(data))
  });
  const json = await res.json();
  if (!res.ok) throw new Error(JSON.stringify(json.error || json));
  return json;
}

// ── Quiz data ─────────────────────────────────────────────────────────────────
// mc(question, [options], correctIndex, explanationIfCorrect, explanationIfWrong)
// tf(question, correctIndex 0=True/1=False, explanationIfCorrect, explanationIfWrong)

const mc = (q, o, c, ec, ew) => ({ type:'mc', question:q, options:o, correct:c, explanation_correct:ec, explanation_wrong:ew });
const tf = (q, c, ec, ew)    => ({ type:'tf', question:q, options:['True','False'], correct:c, explanation_correct:ec, explanation_wrong:ew });

const QUIZZES = {
'ch-3':  [ mc('What widespread language allowed the gospel to spread rapidly across the Roman world?',['Latin','Greek','Hebrew','Aramaic'],1,'Greek was the common tongue of the empire, letting the gospel reach every nation without a language barrier.','Latin was Rome\'s official language but Greek was the universal everyday language across provinces.'), tf('God providentially used the Roman Empire\'s road systems and political unity to advance the gospel, even though Rome never intended this.',0,'Ellen White explains that God guided world history so every condition was perfect when Christ came.','The chapter shows God\'s hand in Roman infrastructure — roads, peace, and a common language all served His purposes.') ],

'ch-4':  [ mc('What promise had the Holy Spirit made to Simeon that brought him to the temple on the day of Jesus\' presentation?',['He would live to become high priest','He would not die until he saw the Messiah','He would see Jerusalem freed from Rome','He would witness a great revival'],1,'The Spirit had given Simeon a personal assurance that his eyes would see the Lord\'s Christ before death.','No political or priestly reward was promised — only the privilege of seeing the Savior with his own eyes.'), tf('Anna the prophetess had been a widow for 84 years when she encountered the infant Jesus in the temple.',0,'Luke 2:37 records she lived with her husband 7 years, then remained a widow until 84, constantly at the temple in prayer.','She had indeed been a widow for 84 years — a remarkable life of faithful waiting and prayer.') ],

'ch-5':  [ mc('For how many days did Mary and Joseph search before finding the 12-year-old Jesus in the temple?',['One day','Two days','Three days','One week'],2,'Luke 2:46 — after a day\'s journey back and a day searching Jerusalem, they found Him on the third day.','The search took three full days: one day\'s travel, one returning to Jerusalem, then finding Him in the temple.'), tf('After returning to Nazareth, Jesus was rebellious and asserted His divine authority over His parents.',1,'Luke 2:51 says He "went down with them and was subject to them," modeling perfect obedience even as the Son of God.','Scripture is clear — Jesus voluntarily submitted to His parents and grew in wisdom, stature, and favor with God and man.') ],

'ch-6':  [ mc('After Joseph\'s death, what did Jesus do that most reveals His self-sacrificing character?',['He immediately began His public ministry','He took up the carpenter trade to support His mother and siblings','He moved to Jerusalem to study under rabbis','He entered the wilderness to pray'],1,'Jesus delayed His mission to provide for the family as breadwinner, showing selfless love for those in His care.','Rather than rushing to claim His destiny, Jesus quietly served His earthly family as a carpenter for years.'), tf('The people of Nazareth consistently recognized Jesus as spiritually superior during His youth and gave Him great honor.',1,'His neighbors knew Him only as a craftsman\'s son. When He later claimed the Messiah\'s role they were offended and nearly killed Him.','Ellen White shows that Jesus was largely unrecognized in His hometown, misunderstood even by those closest to Him.') ],

'ch-7':  [ mc('Unlike other Jewish teachers, John the Baptist received his preparation for ministry:',['Under the famous rabbi Gamaliel in Jerusalem','In the Essene community by the Dead Sea','In the wilderness, away from human tradition and priestly ceremony','In Egypt, as Moses had been'],2,'God educated John apart from the corrupt religious system so his message would be pure and uncompromised.','The wilderness was John\'s seminary — God\'s Spirit was his teacher, not the rabbinical schools of Jerusalem.'), tf('John required Jewish religious leaders to be baptized just as Gentile converts were, which deeply humiliated their pride.',0,'Jewish leaders considered baptism only necessary for Gentile proselytes. To demand it of Abraham\'s descendants was a direct challenge to their self-righteousness.','John\'s insistence struck at the core of Jewish pride — descent from Abraham was no guarantee of God\'s favor.') ],

'ch-8':  [ mc('Why did Jesus insist on being baptized even though He was without sin and John said Jesus should baptize him instead?',['To fulfill an obscure Old Testament ceremonial requirement','To publicly identify with sinful humanity and consecrate Himself to His redemptive mission','To show respect for John\'s ministry','To receive the Holy Spirit, which He lacked before that moment'],1,'By submitting to baptism, Christ placed Himself among sinners He came to save — an act of identification, not of personal need.','Baptism for Jesus was an act of solidarity with humanity, not a sign of repentance — He who knew no sin became sin for us.'), tf('The Holy Spirit descended on Jesus in the form of a dove, and the Father\'s voice from heaven declared His divine sonship at His baptism.',0,'Matthew 3:16-17 records all three members of the Godhead present at this moment — a Trinitarian affirmation of Christ\'s identity.','All three persons of the Godhead were present: the Son being baptized, the Spirit descending, and the Father speaking.') ],

'ch-9':  [ mc('When Satan told Jesus to turn stones to bread, what deeper issue was he really testing?',['Whether Jesus was capable of performing that specific miracle','Whether Jesus would use divine power for self-interest rather than trusting His Father\'s provision','Whether Jesus was truly hungry enough to need food','Whether Jesus had power superior to Satan\'s own'],1,'Satan was not testing hunger — he was tempting Jesus to act independently of the Father, placing self-preservation above God\'s will.','The core issue was trust: would Jesus rely on God\'s timing, or take matters into His own hands at the moment of greatest weakness?'), mc('In the third temptation, Satan offered Jesus all the kingdoms of the world on one condition. What was it?',['That Jesus stop all preaching about repentance','That Jesus jump from the pinnacle of the temple','That Jesus bow down and worship Satan','That Jesus return immediately to heaven'],2,'Satan was seeking worship — the very thing that belongs only to God — in exchange for a shortcut to earthly dominion.','Worship is the heart of the great controversy; Satan wanted to claim it from the Son of God Himself.') ],

'ch-10': [ mc('How did Jesus consistently defeat each of Satan\'s three temptations in the wilderness?',['By commanding angels to silence Satan','By quoting Scripture — specifically from the book of Deuteronomy','By exercising His divine power directly against Satan','By reasoning philosophically until Satan gave up'],1,'Every temptation was answered with "It is written" — Jesus wielded the Word of God as His only weapon.','The same Word available to every believer was Christ\'s weapon of choice, showing us how to fight temptation.'), tf('Jesus\' victory over temptation in the wilderness was only for His own benefit and has no direct bearing on the believer\'s struggle today.',1,'His victory is our victory. Because He overcame as a human depending on the Father, He can give us the same power to overcome.','Ellen White emphasizes that Christ\'s triumph is the pledge of our triumph — He gained it for us, not merely for Himself.') ],

'ch-11': [ mc('When Philip told Nathanael that Jesus of Nazareth was the Messiah, what was Nathanael\'s sceptical response?',['Is He a descendant of David?','Can anything good come out of Nazareth?','Has He studied the Torah properly?','Which tribe is He from?'],1,'Nazareth was a despised backwater town; Nathanael could not imagine the Messiah originating from such a place.','Philip wisely didn\'t argue — he simply said "Come and see," the most effective invitation to encounter Christ.'), tf('Jesus demonstrated supernatural knowledge by telling Nathanael He had seen him sitting under the fig tree before they ever met.',0,'This display of omniscience broke down Nathanael\'s skepticism instantly — "Rabbi, You are the Son of God!"','Jesus saw Nathanael in a private moment, showing divine knowledge that no ordinary person could possess.') ],

'ch-12': [ mc('Immediately after his first encounter with Jesus, what did Andrew do?',['He returned to his fishing nets to think about it','He went straight to find his brother Simon Peter and bring him to Jesus','He traveled to Jerusalem to verify Jesus\' credentials','He sat alone in prayer for several days'],1,'Andrew\'s first impulse was to share what he had found — a model of personal evangelism: find someone you love and bring them to Jesus.','The best witness is an excited discovery shared with those closest to us.'), tf('When Jesus first met Simon, He immediately renamed him Peter (meaning "rock"), showing His foreknowledge of Simon\'s ultimate character.',0,'Despite Simon\'s impulsive nature, Jesus saw what he would become through grace — a rock of strength for the early church.','Ellen White notes that Jesus looks not at what we are but at what He can make us through His transforming power.') ],

'ch-13': [ mc('When the master of the feast tasted the wine Jesus had made at Cana, how did he compare it to what was served earlier?',['It was noticeably inferior','It was identical — no one could tell the difference','It was superior — the best wine of the evening','He refused to comment out of politeness'],2,'Jesus\' creative miracle produced wine of the highest quality — a principle that whatever Christ creates or transforms is always better.','God never gives second-rate gifts. The wine Jesus made put to shame everything the host had provided.'), tf('The miracle at Cana was the first of Jesus\' public signs, performed to manifest His glory and help His disciples believe.',0,'John 2:11 explicitly calls this "the beginning of signs" — it revealed His glory and His disciples believed in Him.','John records this as the inaugural miracle of Christ\'s public ministry, strategically placed at a moment of human need.') ],

'ch-14': [ mc('What gave Jesus the authority that made even the strongest money-changers flee when He cleansed the temple?',['A large group of disciples backing Him up','Roman soldiers who arrived to assist Him','A divine light and holy authority visibly radiating from His presence','An official letter of authority from the Sanhedrin'],2,'Ellen White describes a divine majesty in His look that no human force could withstand — the authority of heaven itself.','No earthly power stood behind Him — only the authority of the Son of God, which was more than sufficient.'), tf('The Jewish chief priests were pleased with Jesus for driving out the corrupt merchants, since they too wanted the abuse to stop.',1,'The religious leaders were furious. They demanded to know by what authority He acted — they profited from the very system He disrupted.','The priests were complicit in the corruption of the temple market. Jesus\' action threatened their revenue and authority.') ],

'ch-15': [ mc('Why did Nicodemus choose to come to Jesus at night rather than during the day?',['He worked full days and was only free after dark','He was afraid of being seen by fellow Pharisees and losing his position','He believed Jesus taught more powerfully in quieter settings','He wanted a shorter queue to speak with Jesus privately'],1,'Ellen White is clear: Nicodemus feared the scorn of his peers. Coming by night was an act of spiritual curiosity mingled with social cowardice.','A member of the Sanhedrin visiting the controversial Galilean teacher openly would have been politically dangerous to his reputation.'), tf('When Jesus said "You must be born again," Nicodemus immediately grasped the spiritual meaning of a renewed heart and mind.',1,'Nicodemus was confused and asked literally: "Can a man enter his mother\'s womb a second time?" — showing he missed the spiritual meaning entirely.','The concept of spiritual rebirth was beyond Nicodemus\' religious framework at that moment, though he later came to understand.') ],

'ch-16': [ mc('To explain the plan of salvation in John 3, Jesus compared His crucifixion to what event in Israel\'s wilderness journey?',['Elijah calling fire down from heaven on Mount Carmel','Moses striking the rock to bring forth water','Moses lifting up the bronze serpent so all who looked would live','The manna falling daily from heaven'],2,'Numbers 21 — as Israel looked to the lifted serpent and lived, so all who look to the lifted Christ in faith receive eternal life.','The serpent on the pole was a type of Christ: lifted up, bearing what brought death, so that looking in faith brings healing.'), tf('According to John 3:16, God\'s love that sent Christ is conditional on human merit and limited to those who are already righteous.',1,'John 3:16 says God loved "the world" — the undeserving, the rebellious, the entire human race — not those who had earned His love.','The entire point of the verse is that God loved us while we were sinners, not because we were worthy of that love.') ],

'ch-17': [ mc('Why were the disciples astonished to find Jesus conversing with the Samaritan woman at Jacob\'s Well?',['Women were forbidden by law to draw water in daylight','Jews and Samaritans carried centuries of bitter racial and religious hostility toward each other','The woman was a known criminal with a public record','Jesus had specifically said He would not speak with strangers that day'],1,'Jews had no dealings with Samaritans — they were despised as racial and religious half-breeds. Jesus crossing this barrier was shocking.','The depth of Jewish-Samaritan animosity made Christ\'s gracious conversation a radical and deliberate breaking of social barriers.'), tf('After meeting Jesus, the Samaritan woman kept the news private because she feared others would not believe her story.',1,'She immediately ran into the city saying "Come see a man who told me everything I ever did. Could this be the Christ?" Many believed because of her testimony.','She became an instant evangelist — the very one who came to the well in shame became the one who brought her whole city to the Savior.') ],

'ch-18': [ mc('John the Baptist\'s question from prison — "Are you the Coming One, or should we look for another?" — is best understood as:',['A complete collapse of his faith in Jesus','The natural human struggle to trust God when suffering contradicts our expectations of how the Messiah would act','Evidence that John believed Jesus had abandoned His mission','A test staged by John on behalf of the Sanhedrin to trap Jesus'],1,'Even the greatest prophets experience dark moments of doubt when circumstances contradict their expectations. John expected a conquering Messiah, not one who left him in prison.','Ellen White treats John\'s question with deep compassion — suffering can cloud even the clearest prophetic vision.'), tf('Jesus responded to John\'s messengers with a stern rebuke, telling them that John needed to strengthen his wavering faith immediately.',1,'Jesus pointed to evidence: "The blind receive sight, the lame walk, the dead are raised, the poor have good news preached." He let the facts speak.','Christ never rebuked John. Instead He gave him reasons to believe and then publicly praised him as the greatest of prophets born of woman.') ],

'ch-19': [ mc('The healing of the Capernaum nobleman\'s son, performed from miles away, demonstrated what truth about Jesus\' power?',['Healing required the sick person to touch Jesus or His garment','Jesus needed to know the sick person personally to heal them','Jesus\' healing power was not limited by physical distance','Jesus would only heal those who had come to Him directly'],2,'Jesus spoke the word and the boy was healed at that exact hour — distance presented no obstacle to divine power.','No barriers of space or time limit Christ\'s ability to act on behalf of those who trust in Him.'), tf('The nobleman initially came demanding a miracle but then believed Jesus\' spoken word before any physical confirmation arrived.',0,'The man "believed the word Jesus spoke" and departed — the healing was confirmed only when he met his servants on the way home.','True faith acts on the word of Christ before circumstances confirm it. The nobleman modeled this kind of believing trust.') ],

'ch-20': [ mc('When Jesus read from Isaiah in the Nazareth synagogue and said "Today this Scripture is fulfilled in your hearing," the congregation\'s reaction was:',['Immediate belief and joyful worship','Initial wonder that turned into rage and rejection when He pointed to their unbelief','Deep repentance and a request for Him to stay and teach them','Calm scholarly debate about the interpretation of Isaiah'],1,'They marveled at first, then became furious when He pointed out how Israel had historically rejected its own prophets in favor of Gentiles.','Their local pride turned to murderous anger the moment Jesus suggested Gentiles might receive blessings Israel would reject.'), tf('The Nazareth mob attempted to throw Jesus off a cliff, but He calmly walked through the crowd and continued on His way.',0,'Luke 4:30 — He passed through their midst and went on His way, His time not yet come. His composure was itself a miracle.','The crowd had no power over Him — He departed with sovereign calm, not fleeing in fear but walking through them in divine dignity.') ],

'ch-21': [ mc('After the miraculous catch of fish that filled two boats nearly to sinking, Simon Peter\'s immediate response was:',['Amazement and an offer to share the catch with the poor','"Depart from me, Lord, for I am a sinful man!"','A request to learn how to perform such miracles himself','Gratitude and an invitation for Jesus to his home'],1,'The abundance of the miracle revealed Jesus\' divine power, which made Peter acutely aware of his own sinfulness by contrast.','Encountering the holy always produces this response — Isaiah said "Woe is me!" and Peter said "Depart from me." Holiness reveals our need.'), tf('Peter, James, John, and Andrew left their boats, their nets, and their livelihoods the very day Jesus called them, following without hesitation.',0,'Luke 5:11 — "They left everything and followed Him." The immediacy and totality of their response was remarkable.','These fishermen had a thriving business. The fact they left everything in that moment shows the compelling power of Christ\'s call.') ],

'ch-22': [ mc('When Jesus cast out an unclean spirit in the Capernaum synagogue, what did the demon cry out that revealed Jesus\' true identity?',['"You have no power over us here!"','"We are many and cannot be defeated!"','"I know who You are — the Holy One of God!"','"Come out of this holy place!"'],2,'Even demons recognized and confessed Jesus\' divine identity, though they served their master in doing so.','Satan\'s forces knew exactly who Jesus was — their terror in His presence was itself a testimony to His divine nature.'), tf('After healing Peter\'s mother-in-law of fever, Jesus then healed every sick and demon-possessed person the entire city brought to Him that evening.',0,'Mark 1:33-34 — "The whole city was gathered at the door" and He healed many. It was a night of extraordinary mercy.','The Sabbath ended at sunset, and immediately the people came. Jesus healed all who came without exception.') ],

'ch-23': [ mc('When the leper said "If You are willing, You can make me clean," Jesus did something that no Jewish law permitted — He:',['Prayed over the leper from a safe distance','Sent him to the priests to be declared clean first','Touched the leper, saying "I am willing; be cleansed"','Asked the crowd to step back before performing the miracle'],2,'Jesus touched the untouchable. His touch did not make Him unclean — His holiness made the leper clean.','Levitical law made the leper untouchable, yet Jesus reached out and touched him — meeting human misery with holy compassion.'), tf('After healing the leper, Jesus instructed him to tell no one and first show himself to the priest as a legal testimony.',0,'Mark 1:44 — Jesus instructed him to present himself to the priest and offer the gift Moses commanded, a witness to the authorities.','The healing was private but the testimony was to be official — a legal certification that something extraordinary had taken place.') ],

'ch-24': [ mc('When Jesus saw the faith of the four men who lowered their paralyzed friend through the roof, He first said:',['Rise, take up your mat and walk','Your faith has healed you','Your sins are forgiven you','Be made whole in body and spirit'],2,'Jesus addressed the deeper problem first — sin — then proved His authority to forgive by healing the body.','The scribes accused Him of blasphemy at the word of forgiveness, so Jesus healed the man as visible proof of His authority.'), tf('Jesus healed the paralytic specifically to demonstrate to the scribes that the Son of Man has authority on earth to forgive sins.',0,'The miracle was both an act of compassion and a deliberate claim: if He could heal the visible, He had authority over the invisible too.','Ellen White shows this healing as a calculated response to the silent accusation of blasphemy — faith was rewarded and critics were silenced.') ],

'ch-25': [ mc('Why were tax collectors like Matthew (Levi) despised by fellow Jews?',['They were known to be violent criminals','They collected taxes for Rome, often extorting more than required, and were considered traitors to Israel','They had refused to be circumcised','They had publicly denied the Jewish faith'],1,'Tax collectors were collaborators with the Roman occupation, socially excluded and religiously condemned by the scribes and Pharisees.','Matthew sat in a toll booth for Rome — in Jewish eyes, no occupation could be more shameful or spiritually disqualifying.'), tf('The Pharisees criticized Jesus for eating with Matthew and other tax collectors, and Jesus replied that it is not the healthy who need a doctor but the sick.',0,'Jesus turned their criticism into a declaration of His mission: He came to call sinners, not the self-righteous, to repentance.','This response is one of the clearest statements of why Jesus associated with the outcasts — they were exactly the people He came to save.') ],

'ch-26': [ mc('What did Jesus do the night before choosing His twelve apostles that set this decision apart from all others?',['He fasted for forty days as He had before the temptation','He spent the entire night in prayer on a mountain','He consulted with John the Baptist in prison','He gathered the seventy disciples to take a vote'],1,'Luke 6:12 — He spent the whole night in prayer. The choice of twelve men to carry the gospel to the world required extraordinary divine guidance.','No other decision in His ministry demanded more prayer — these twelve would carry His message to every generation.'), tf('The twelve apostles Jesus chose were all educated scholars from respected religious families who had formal rabbinical training.',1,'They were fishermen, a tax collector, a zealot — ordinary men of humble background. God consistently chooses the weak to shame the strong.','Ellen White highlights that Jesus passed by the scholars and chose working men, showing that character and consecration matter more than credentials.') ],

'ch-27': [ mc('In EGW\'s understanding, being "poor in spirit" — the first Beatitude — refers to:',['Poverty from giving all possessions away to the poor','Having no emotional energy or spiritual confidence','Recognizing one\'s complete spiritual bankruptcy and utter dependence on God','Avoiding pride by practicing physical austerity'],2,'Spiritual poverty means seeing yourself as you truly are before God — empty, needy, completely dependent on His grace.','The proud religious leaders felt spiritually rich; the poor in spirit feel their need — and that felt need is the beginning of salvation.'), tf('The Beatitudes describe a progression: each quality Jesus commends naturally flows from and deepens the one before it.',0,'Ellen White shows the Beatitudes as interconnected graces — poverty of spirit leads to mourning over sin, which produces meekness, which hungers for righteousness.','Each Beatitude builds on the last, forming a portrait of the character that Christ forms in those who surrender to Him.') ],

'ch-28': [ mc('When Jesus said "You have heard it said... but I say to you," He was doing what to the Old Testament law?',['Contradicting and abolishing Moses\' commands','Adding new requirements beyond what the law demanded','Revealing the deeper spiritual intent and heart meaning behind the law','Establishing a simplified version of the law for Gentiles'],2,'Jesus did not replace the law — He magnified it, showing that murder begins with anger, adultery with a lustful look.','The Pharisees kept the letter; Jesus demanded the spirit. External compliance was never enough — God looks at the heart.'), tf('Jesus taught that anger without cause puts a person in the same category of spiritual guilt as one who commits physical murder.',0,'Matthew 5:21-22 — Jesus traces the root of murder to the heart, where anger unchecked becomes hatred and then violence.','Ellen White explains that every act of violence begins in the heart; God holds us accountable for what we cultivate in the inner life.') ],

'ch-29': [ mc('The phrase in the Lord\'s Prayer "Thy kingdom come, Thy will be done on earth as it is in heaven" primarily teaches us to pray:',['For a political kingdom to replace Rome','That our personal desires align with God\'s eternal purposes and glory','For the immediate Second Coming of Christ','For health and prosperity as signs of God\'s blessing'],1,'This petition places God\'s will — not our own comfort — at the center of prayer, surrendering our agenda to His sovereign plan.','Prayer is not bending God\'s will to ours; it is bringing our will into conformity with His — this phrase captures that submission perfectly.'), tf('Jesus taught that we must forgive others in order to receive God\'s forgiveness — making our forgiveness of others a condition of being forgiven ourselves.',0,'Matthew 6:14-15 is unmistakable: "If you forgive others... your Heavenly Father will also forgive you. But if you do not forgive, He will not forgive you."','This is not merely a suggestion. Ellen White calls unforgiveness one of the greatest barriers between the soul and God.') ],

'ch-30': [ mc('When the centurion said Jesus need not come to his house but only speak a word, Jesus responded by calling this:',['Presumptuous — faith must be accompanied by proper form','An insult to His willingness to visit Gentile homes','The greatest faith He had encountered in all of Israel','A misunderstanding of how healing worked'],2,'Matthew 8:10 — "I have not found such great faith, not even in Israel." A Gentile soldier understood Christ\'s authority better than most of His own people.','The centurion grasped a principle many miss: Christ\'s authority requires no physical presence — His word alone accomplishes the miracle.'), tf('The centurion believed Jesus could heal his servant despite never having received a direct promise that Jesus would do so.',0,'He came in faith, not demand. His humility — "I am not worthy for You to come under my roof" — combined with bold faith is the model Jesus commended.','True faith does not require guarantees before believing; it trusts Christ\'s character and authority even without a prior promise.') ],

'ch-31': [ mc('What moved Jesus to raise the widow of Nain\'s son, even though no one had asked Him to do so?',['A request from the disciples who knew the family','His desire to prove His power to the watching crowd','Pure compassion — seeing the widow\'s grief moved His heart before any prayer was made','A challenge from Pharisees who doubted His power over death'],2,'Luke 7:13 — "When the Lord saw her, He had compassion on her." Jesus acted on compassion alone — no request, no faith required of her in that moment.','This miracle reveals something profound: Jesus sometimes acts not because we ask or deserve but simply because He sees our need and His heart is moved.'), tf('The raising of the widow\'s son caused fear to come upon all present, and they glorified God saying "A great prophet has risen among us."',0,'Luke 7:16 — the crowd\'s response was reverent awe and praise to God. A dead man sat up and began to speak, and Jesus gave him to his mother.','The parallel to Elijah raising the widow\'s son at Zarephath was not lost on the crowd — they recognized a prophetic echo.') ],

'ch-32': [ mc('When the sinful woman wept and anointed Jesus\' feet in Simon\'s house, Jesus used the Parable of Two Debtors to teach:',['That all financial debts must eventually be repaid','That those who are forgiven much will love much in return','That Simon was a worse sinner than the woman','That the woman\'s tears were unnecessary since her sins were already forgiven'],1,'The one forgiven a greater debt loves more — the woman\'s extravagant love flowed from her deep awareness of how much she had been forgiven.','Love for Christ is always proportional to our understanding of how much we have been forgiven. The self-righteous love little because they see little need.'), tf('Simon the Pharisee, who hosted Jesus for dinner, provided all the standard courtesies of hospitality — water, oil, and a greeting.',1,'Simon provided nothing: no water for dusty feet, no oil for the head, no kiss of greeting. The sinful woman, however, gave all of these through her tears and ointment.','Ellen White uses this contrast sharply — the "respectable" host offered cold formality while the broken sinner offered lavish, costly love.') ],

'ch-33': [ mc('Jesus used parables as His primary teaching method with the multitudes. One key reason was:',['He lacked formal training for direct theological discourse','To keep all truth permanently hidden so only the twelve could understand','To communicate truth so that the spiritually receptive could grasp it while those rejecting truth would not receive it to their further condemnation','To fulfill a specific rabbinic teaching tradition of his day'],2,'Parables function as self-selecting filters: those with open hearts receive truth; those hardened by rejection are spared adding to their guilt.','Ellen White explains that parables are acts of mercy — truth wrapped in stories reaches willing hearts while not increasing condemnation for those who resist.'), tf('In the Parable of the Sower, the seed falling on rocky ground represents people who receive the word joyfully but have no root — they fall away when persecution comes.',0,'Mark 4:16-17 — emotional enthusiasm without deep root cannot survive the heat of trial. Feeling and faith are not the same thing.','Many receive the gospel with initial excitement; the test is whether that initial response deepens into rooted, enduring commitment.') ],

'ch-34': [ mc('When a violent storm threatened to sink the disciples\' boat on the Sea of Galilee, where was Jesus?',['Standing at the bow watching the storm','Praying at the stern with His eyes open','Asleep on a cushion in the stern, exhausted from the day\'s ministry','Swimming alongside the boat encouraging the disciples'],2,'Mark 4:38 — He was asleep, genuinely tired. This detail is evidence of His true humanity alongside His true divinity.','The One who created the sea was asleep in a boat on it — fully God, fully human, genuinely exhausted from selfless service to others.'), tf('After Jesus calmed the storm with a word, the disciples were completely at peace and full of faith, having seen His power.',1,'They were terrified — asking one another "Who can this be that even the wind and sea obey Him?" The miracle deepened their awe but also their bewilderment.','Ellen White notes the disciples were as afraid after the calming as during the storm — they had witnessed something utterly beyond human explanation.') ],

'ch-35': [ mc('When the Gadarene demoniac was freed by Jesus, what did the once-demon-possessed man beg to do?',['Return immediately to his home village','Follow Jesus and leave the region with Him','Go warn the Decapolis cities about the power of Satan','Stay alone in the tombs in gratitude and prayer'],1,'Mark 5:18 — "he begged to be with Him." The delivered man wanted to follow Jesus. But Christ gave him a different assignment.'), tf('Jesus told the healed Gadarene to follow Him to Galilee, since his testimony would not be believed in his home region of the Decapolis.',1,'Jesus told him to "Go home to your friends, and tell them what great things the Lord has done for you." He was sent as a missionary to his own people.','Ellen White shows that the most powerful testimony is often given right where we are most known — where our transformation is most visible.') ],

'ch-36': [ mc('The woman who had been ill for twelve years and touched Jesus\' garment was initially afraid to identify herself. Why did Jesus insist on drawing her out publicly?',['To rebuke her for touching Him without permission','To complete her healing — public acknowledgment of what Christ does for us is part of the blessing','To use her as a lesson for the crowd on how to ask for miracles','To verify that she was healed before He continued to Jairus\'s house'],1,'Jesus wanted her testimony — not just her healing. A secret blessing that is never shared cannot encourage others who face the same suffering.','Ellen White explains that Christ draws the healed woman forward so her faith can be a testimony, and so she leaves with peace rather than fear.'), tf('While Jesus was speaking with the healed woman, news came that Jairus\'s daughter had died, and Jesus told Jairus "Do not be afraid; only believe."',0,'Mark 5:36 — the most devastating news arrived at the worst moment, and Jesus\' response was a call to hold faith against the evidence.','When everything seems to contradict hope, Christ\'s word is still enough. "Only believe" — those two words changed the outcome for an entire household.') ],

'ch-37': [ mc('When the disciples urged Jesus to send the hungry crowd away to buy food, His surprising counter-instruction was:',['Let them fast — it will purify their faith','Ask the Pharisees who follow us to provide for them','You give them something to eat yourselves','Gather what you can and distribute it equally, however small the amount'],2,'Jesus placed the responsibility back on the disciples — not to overwhelm them but to lead them to discover that sufficiency comes through Him.','They had five loaves and two fish. Jesus took what was impossibly small and made it enough for five thousand, teaching that He multiplies what we surrender.'), tf('After feeding the five thousand, the disciples collected only a few leftover scraps — most of the food had been consumed entirely.',1,'Twelve baskets of fragments remained — one for each doubting disciple, perhaps. Abundance overflowed where scarcity had begun.','The leftovers exceeded what they started with, demonstrating that Christ\'s supply always surpasses human need when given into His hands.') ],

'ch-38': [ mc('When Peter stepped out of the boat to walk on water toward Jesus, why did he begin to sink?',['The weight of his sandals dragged him down','Jesus momentarily withdrew His power as a test of endurance','He took his eyes off Jesus and focused on the frightening wind and waves around him','A large wave knocked him off balance'],2,'Matthew 14:30 — "When he saw the wind, he was afraid." The moment attention shifted from Christ to circumstances, faith failed.','This is one of the clearest illustrations in Scripture of what happens when we look at the storm instead of the Savior.'), tf('After Peter sank and cried "Lord, save me!" Jesus pulled him up and immediately said "O you of little faith, why did you doubt?"',0,'Matthew 14:31 — rescue first, question second. Christ never lets us drown before He teaches us; He saves us and then helps us understand what went wrong.','The sequence matters: Jesus extended His hand immediately. The gentle rebuke came after Peter was already safe.') ],

'ch-39': [ mc('After Jesus\' teaching "I am the Bread of Life" in the Capernaum synagogue, what was the shocking reaction among His followers?',['A great revival as thousands gave their lives to Him','Many disciples turned back and no longer walked with Him','The Pharisees arrested Him but the disciples protected Him','The crowd demanded He repeat the miracle of the loaves'],1,'John 6:66 — "From that time many of His disciples went back and walked with Him no more." Hard truth drove away the crowd-pleasers.','The Bread of Life discourse separated genuine seekers from those following Jesus for miracles and material benefit.'), tf('When Jesus asked the Twelve if they would also leave, Peter answered "Lord, to whom shall we go? You have the words of eternal life."',0,'John 6:68 — Peter\'s answer is one of the greatest confessions in Scripture: not "I have no doubt" but "Where else would we go? You alone have what we need."','Peter did not claim perfect understanding. He simply acknowledged that Jesus had no rival as the source of eternal life.') ],

'ch-40': [ mc('Jesus confronted the Pharisees about the tradition of "Corban" because it allowed people to avoid their duty of:',['Paying the annual temple tax','Supporting their aging parents financially, violating the fifth commandment to honor father and mother','Tithing the firstfruits of their harvest','Serving in the temple as required by law'],1,'Mark 7:11-12 — by declaring money "dedicated to God," people could legally refuse to support their needy parents. Jesus exposed this as human tradition nullifying God\'s command.','Religious technicalities were being used to avoid basic human obligations — a clear case of letter-keeping that violated the spirit of the law.'), tf('Jesus taught that what truly defiles a person spiritually is not eating with unwashed hands or eating certain foods, but evil thoughts that come from within the heart.',0,'Mark 7:20-23 — Jesus gives an explicit list: evil thoughts, sexual immorality, theft, murder, greed, malice... all come from within.','External ritual could never make the heart clean. Only Christ\'s transforming grace addresses the real source of defilement.') ],

'ch-41': [ mc('The Syrophoenician woman persisted in asking Jesus to heal her daughter despite what seemed like a dismissive initial response. This persistence demonstrated:',['That being rude to Jesus will eventually get results','That faith is not discouraged by apparent obstacles or delays — it presses through to the heart of God','That Gentiles had to prove greater faith than Jews to receive the same blessing','That Jesus was testing all non-Jewish seekers before helping them'],1,'Jesus was drawing out her faith, not refusing it. She understood His character well enough to hold on — and He commended her faith as great.','The apparent obstacle was not rejection but an invitation to deeper faith. Those who press through apparent silence find Christ\'s heart open to them.'), tf('Jesus ultimately refused to heal the Syrophoenician woman\'s daughter because she was a Gentile outside the covenant promises.',1,'Jesus healed her daughter and said "O woman, great is your faith! Let it be to you as you desire." Her persistence was rewarded with the full miracle.','Ellen White shows this as evidence that the gospel was already reaching beyond Israel — Gentile faith moved the heart of the Jewish Messiah.') ],

'ch-42': [ mc('When the Pharisees demanded a sign from heaven to prove Jesus\' divine authority, He said the only sign they would be given was:',['The healing of a man born blind, performed publicly','A visible display of divine fire from heaven, as with Elijah','The sign of Jonah — three days and nights, pointing to His death and resurrection','The destruction of Jerusalem as He would predict on the Mount of Olives'],2,'The resurrection was the ultimate sign — not a miracle performed for skeptical demands, but the event that would vindicate all His claims.','Signs given to satisfy unbelieving demands only harden the heart further. The resurrection alone would answer all doubts — for those willing to believe.'), tf('Jesus\' refusal to perform miracles on demand for the Pharisees was a sign of weakness — He could not produce miracles under pressure.',1,'He had just fed 4,000 people. His refusal was a moral choice, not a limitation. Miracles to satisfy unbelief were not part of His mission.','Ellen White distinguishes between miracles of compassion and miracles of spectacle. Jesus never performed the latter.') ],

'ch-43': [ mc('When Jesus asked "Who do you say that I am?" and Peter answered "You are the Christ, the Son of the living God," Jesus said this truth was revealed by:',['Peter\'s own spiritual insight and intelligence','The accumulated evidence of Jesus\' miracles over three years','The Heavenly Father — flesh and blood had not revealed it to him','The prophets of the Old Testament'],2,'Matthew 16:17 — divine revelation, not human deduction. Saving faith is always the work of the Spirit, not unaided human reasoning.','Peter\'s confession was not a brilliant conclusion he reached on his own — it was given from above, which is why Jesus affirmed it so strongly.'), tf('By saying "on this rock I will build my church," Jesus was declaring the apostle Peter to be the foundational leader and first pope of the church.',1,'Ellen White explicitly states the rock is Christ Himself as confessed by Peter\'s statement — the church is built on who Christ is, not on Peter\'s person.','Catholic tradition differs, but EGW teaches that the foundation is the truth Peter confessed, not Peter\'s office or succession.') ],

'ch-44': [ mc('On the Mount of Transfiguration, the two heavenly visitors who appeared and spoke with Jesus were:',['Abraham and David','Enoch and Elijah','Moses and Elijah','Isaiah and John the Baptist'],2,'Moses represented those who have died and will be resurrected; Elijah represented those translated without seeing death — together, a picture of both groups Christ will redeem.','The choice of these two was deliberate and deeply symbolic: death conquered by resurrection, and the living changed without death.'), tf('The disciples were so terrified by the Transfiguration\'s glory that they fell on their faces, and only Jesus\' touch and voice restored them.',0,'Matthew 17:6-7 — they fell with their faces to the ground. Then Jesus touched them: "Arise, and do not be afraid." His touch breaks every fear.','The glory that overwhelmed them was the same glory that daily walked among them in veiled form — they glimpsed who He always was.') ],

'ch-45': [ mc('When the disciples asked "Who then is greatest in the kingdom of heaven?" after arguing among themselves, Jesus placed a child in their midst and said:',['Greatness belongs to those who study the Scriptures most diligently','Unless you are converted and become like children, you will not even enter the kingdom — let alone be greatest','The greatest among you is the one with the longest record of service','Greatness is measured by the number of miracles performed in My name'],1,'Matthew 18:3-4 — humble, trusting, unselfconscious dependence on the Father is the kingdom\'s definition of greatness.','The disciples were arguing about position; Jesus pointed to a child — the very one they would have considered least — as the model of kingdom character.'), tf('The disciples could not cast out the epileptic boy\'s demon because they lacked the proper official authority delegated by Jesus.',1,'Jesus said "this kind does not go out except by prayer and fasting" — the issue was their prayerlessness and self-reliance, not insufficient authority.','They had been given authority; what they lacked was the humility and dependence on God that makes authority effective.') ],

'ch-46': [ mc('At the Feast of Tabernacles (John 7), Jesus taught openly in the temple though the religious leaders sought to arrest Him. The people were divided — those who believed said He was:',['Clearly the political messiah they had been waiting for','The Prophet, or the Christ, while others said He deceived the people','A good teacher who should be given more time to prove himself','Probably Elijah, returned before the great day of the Lord'],1,'John 7:40-43 — the crowd was genuinely split between recognizing Him as the Christ and believing He was a deceiver. Neutrality was not an option.','Jesus never allowed people to remain indifferent — His presence and words always divided those who heard them.'), tf('On the last great day of the Feast of Tabernacles, Jesus stood and cried out "If anyone thirsts, let him come to Me and drink," referring to the Holy Spirit.',0,'John 7:37-39 — this dramatic declaration on the greatest day of the water-pouring ceremony was unmistakably Messianic.','The feast\'s water ceremony symbolized the Spirit\'s outpouring in the Messianic age. Jesus declared Himself the fulfillment of what they had been acting out.') ],

'ch-47': [ mc('When the scribes and Pharisees brought a woman caught in adultery to trap Jesus, His first response was to:',['Immediately pronounce her forgiven to show His mercy','Ask the crowd to take a vote on what should be done','Stoop down and write in the ground without immediately answering them','Call for the legal proceedings to follow Mosaic law'],2,'John 8:6,8 — He bent down and wrote in the ground, twice. What He wrote is not recorded, but the action bought time and turned attention from the crowd.','His pause and writing defused the public spectacle the accusers needed. By the time He spoke, the trap had been dissolved.'), tf('After her accusers left one by one, Jesus told the woman that because she had shown courage He would declare her innocent of the charges.',1,'Jesus said "Neither do I condemn you; go and sin no more." He did not excuse the sin but offered a fresh start — forgiveness with a call to transformation.','"Go and sin no more" is as important as "neither do I condemn you." Christ offers no forgiveness that is not also a call to a changed life.') ],

'ch-48': [ mc('When Jesus said "Before Abraham was, I AM," the Jewish leaders immediately took up stones to kill Him because they understood He was:',['Making an impossible historical claim they found confusing','Claiming eternal divine pre-existence — the name "I AM" was the sacred name of God revealed to Moses'],['Speaking carelessly and in need of correction'],['Claiming to be Abraham\'s direct descendant'],1,'The "I AM" was not a grammatical mistake — it was the divine name of Exodus 3:14. The Jews understood perfectly and responded with murderous rage.','"I AM" is not a claim to be a great teacher; it is a claim to be God Himself. The Jews could not misunderstand it — that is why they reached for stones.'), tf('Jesus told the Pharisees in John 8 "You are of your father the devil," because they sought to kill Him and rejected the truth He spoke.',0,'John 8:44 — Jesus traced their murderous intentions and love of falsehood back to their spiritual parentage. It was the most confrontational statement of His ministry.','By calling them children of the devil, Jesus was not insulting them — He was diagnosing their condition so they could seek the cure.') ],

'ch-49': [ mc('When the disciples asked whether the man born blind had sinned or his parents causing his blindness, Jesus corrected them by saying:',['It was the man\'s own unconfessed sin from a prior life','It was his parents\' generational sin passed down to him','Neither — it was so that the works of God could be revealed in him','Blindness was always the result of specific personal sin'],2,'John 9:3 — Jesus rejected both options and reframed the question entirely. Suffering is not always punishment; sometimes it is the stage for a divine display.','This answer liberates people suffering from false guilt. Not every affliction is a punishment — some are appointments for God\'s glory to be revealed.'), tf('After Jesus healed him, the man born blind was expelled from the synagogue by the Pharisees for insisting that Jesus had healed him.',0,'John 9:34 — "They cast him out." Confession of what Christ has done for us can cost everything socially and religiously. He paid that price without hesitation.','The formerly blind man had no theological training, but he had an irrefutable testimony: "One thing I know — I was blind, and now I see."') ],

'ch-50': [ mc('Jesus said the Good Shepherd differs from a hired hand in one decisive way. What is it?',['The shepherd owns a staff; the hireling does not','The Good Shepherd knows His sheep by name; the hireling treats them as numbers','The Good Shepherd lays down His life for the sheep; the hireling flees when the wolf comes','The shepherd stays twenty-four hours; the hireling works only by day'],2,'John 10:11-13 — when danger comes, the decisive test of a true shepherd is revealed. Self-sacrifice separates care from mere employment.','The cross is the ultimate proof of John 10:11. Jesus said He would lay down His life — and He did, not as victim but as the willing Shepherd.'), tf('Jesus said He has "other sheep" not of the Jewish fold that He must bring, and they will hear His voice, resulting in one flock and one Shepherd.',0,'John 10:16 — the Gentile mission was not an afterthought. Jesus already anticipated and planned for the universal scope of His redemption.','From the beginning the Good Shepherd\'s flock was never meant to be limited to Israel — all the Father gives to Him will come to Him.') ],
};

// ── Chapters 51-87 quiz data (continued below) ───────────────────────────────

const QUIZZES2 = {
'ch-51': [ mc('When Jesus received word that Lazarus was sick, why did He deliberately wait two more days before traveling to Bethany?',['He was too busy to leave the Jordan region immediately','The disciples warned Him it was too dangerous to go near Jerusalem','So that God\'s glory would be shown in a greater miracle than healing a sick man','He was testing whether Mary and Martha\'s faith was genuine'],2,'John 11:4,6 — Jesus loved Lazarus, yet waited. The delay was purposeful: a healing would have been wonderful; a resurrection would be unforgettable.','Ellen White shows that apparent delays are never divine indifference. Sometimes God waits to do something greater than what we asked.'), tf('Martha said "I know that my brother will rise again in the resurrection at the last day," showing she had fully grasped that Jesus could raise Lazarus immediately.',1,'She believed in a distant future resurrection but had not yet connected that truth to the Person standing before her who IS the resurrection.','Jesus then said "I am the resurrection and the life" — pointing her from a doctrine about the future to a Person present with her now.') ],

'ch-52': [ mc('Before commanding Lazarus to come forth, Jesus wept at the tomb. This weeping reveals:',['That Jesus doubted whether the Father would grant this miracle','That He grieved as a human being, sharing in the sorrow of those He loved, even knowing He would raise Lazarus','That He was lamenting Israel\'s lack of faith','That He was performing for the crowd\'s emotional response'],1,'John 11:35 — the shortest verse in the Bible carries enormous weight. Jesus wept. He knew the outcome, yet He fully entered into the grief of the moment.','Christ did not stand outside our sorrow and observe it — He entered it. He weeps with those who weep even while He moves to transform the situation.'), tf('The resurrection of Lazarus was the miracle that finally convinced the Sanhedrin to officially plot to put Jesus to death.',0,'John 11:47-53 — the evidence that should have produced belief instead produced a council meeting to plan murder. Hardened hearts reject the most powerful evidence.','Ellen White notes the bitter irony: the miracle of life given to one man became the occasion for planning death against the One who gave it.') ],

'ch-53': [ mc('Caiaphas said "It is expedient that one man die for the people, rather than the whole nation perish." Ellen White explains this was:',['A purely cynical political calculation with no spiritual significance','An unconscious prophecy given through him in his role as high priest about Christ\'s atoning death for the world','A misquotation of the Torah that Jesus would later correct','An expression of genuine concern for Israel\'s spiritual welfare'],1,'John 11:51 — John explicitly says Caiaphas prophesied this, not speaking of himself. The high priestly office occasionally carried unwilling prophetic function.','God can use even the words of His enemies to proclaim His purposes. Caiaphas meant it politically; the Spirit meant it redemptively.'), tf('After the Sanhedrin\'s formal decision to kill Jesus, He immediately returned to Jerusalem to confront them directly.',1,'Jesus withdrew to a region near the wilderness and continued His ministry there until the time was fully come.','His life was not taken — it was laid down on His own terms, at the time and in the way the Father had appointed.') ],

'ch-54': [ mc('When the rich young ruler asked what he must do to inherit eternal life and Jesus told him to sell all and follow Him, what did the young man do?',['He joyfully complied, giving away his wealth that same day','He argued that the law did not actually require such sacrifice','He went away sorrowful, because he had great possessions','He asked if he could give half instead'],2,'Mark 10:22 — sorrow, not rebellion. He genuinely wanted eternal life but wanted his wealth more. The treasure he chose could not satisfy the longing he had.','Ellen White identifies the idol: not wealth itself but the love of it. He kept his money and lost the one thing he said he wanted most.'), tf('After the rich young ruler left, Jesus said it is easier for a camel to pass through the eye of a needle than for a rich man to enter God\'s kingdom.',0,'Mark 10:25 — the disciples were astonished, asking "Who then can be saved?" Jesus replied "With men it is impossible, but not with God."','The problem is not money but the heart that trusts in it. What is impossible for us is possible when we surrender to God\'s transforming grace.') ],

'ch-55': [ mc('Why did the crowd murmur when Jesus chose to stay at Zacchaeus\' house rather than a more respectable home?',['Zacchaeus\'s house was too small for a proper dinner gathering','Zacchaeus was a chief tax collector — a notorious collaborator with Rome and extorter of his own people','Jesus had previously promised to stay with the synagogue ruler that day','Zacchaeus had not officially invited Jesus — it was considered rude'],1,'Luke 19:7 — "He has gone to be the guest of a man who is a sinner." In Jericho, no one was more despised than the chief tax collector.','Jesus always seemed to head toward the most unlikely person in the crowd — the one everyone else had written off.'), tf('Zacchaeus promised to give half his goods to the poor and restore fourfold to anyone he had defrauded.',0,'Luke 19:8 — his response to salvation was immediate and radical generosity. Real encounter with Christ always produces tangible transformation.','Ellen White shows Zacchaeus\'s restitution as proof of genuine conversion: not just words, but costly action that demonstrated a changed heart.') ],

'ch-56': [ mc('In the Parable of the Talents, why did the servant who received one talent bury it instead of investing it?',['He was planning to invest it once conditions were safer','He feared his master and convinced himself that the safest course was to preserve what he had been given','He was secretly planning to steal it for himself','He disagreed with the master\'s system and wanted to protest by non-participation'],1,'Matthew 25:25 — "I was afraid." Fear, not malice, paralyzed him. He had a distorted view of his master that made faithful service seem pointless.','Ellen White identifies this servant\'s sin as the sin of a wrong conception of God — seeing Him as harsh rather than gracious and worthy of joyful service.'), tf('The servant who buried his talent was commended for his caution and prudence — better to preserve what you have than to risk losing it.',1,'He was rebuked and the talent taken from him. Even the minimum — putting it in the bank — would have been better than burying it.','"Use it or lose it" is the spiritual principle here. God\'s gifts are not given to be hoarded; unused gifts atrophy and are eventually withdrawn.') ],

'ch-57': [ mc('Jesus entered Jerusalem riding on a donkey in deliberate fulfillment of which prophecy?',['Isaiah 9:6 — "For unto us a Child is born"','Zechariah 9:9 — "Your King comes to you, lowly, riding on a donkey"','Micah 5:2 — "Out of Bethlehem shall come a Ruler"','Malachi 3:1 — "the Lord will suddenly come to His temple"'],1,'Every detail was intentional: the humble animal, the specific route, the timing — all fulfilling ancient prophecy to the letter.','Ellen White notes that Jesus orchestrated this entry deliberately. For the first and only time He accepted the public acclamation of the crowds.'), tf('When the Pharisees asked Jesus to rebuke His disciples for praising Him, Jesus said if they were silent the very stones would cry out.',0,'Luke 19:40 — a remarkable statement: the praise was not merely appropriate, it was cosmically required. Creation itself would respond if humanity failed.','Ellen White writes that even nature recognized its Creator — if human voices were silenced, inanimate stones would have burst into praise.') ],

'ch-58': [ mc('When Jesus cursed the fig tree that had leaves but no fruit, the primary spiritual lesson for Israel was:',['That fig trees found near roads must produce fruit or be removed','That Israel, showing impressive outward religion but no real fruit of faith, faced the same judgment','That miracles of destruction were a standard part of Jesus\' ministry','That Jesus was genuinely angry due to hunger and acted impulsively'],1,'The fig tree was a living parable of Israel: spectacular religious show — the temple, the rituals, the traditions — but no genuine spiritual fruit.','Form without substance, profession without transformation — the cursed fig tree is a warning to every generation not just to Israel.'), tf('The second cleansing of the temple at the end of Jesus\' ministry was the first time He had driven out merchants — He had not done this before.',1,'The first cleansing was at the beginning of His ministry (John 2). The second, near the end, showed the merchants had returned and the corruption had resumed.','Two cleansings bracket Jesus\' public ministry — the first at the start, the last in Passion Week, bookending His mission with the same cry for holiness.') ],

'ch-59': [ mc('In the Parable of the Wicked Vinedressers, who does the beloved son represent who is killed by the tenants?',['The prophets of the Old Testament who were repeatedly rejected','Jesus Christ, the Son of God, who the leaders of Israel would reject and crucify','The disciples who would be persecuted after the ascension','John the Baptist, the last prophet before Christ'],1,'Matthew 21:38 — "This is the heir. Come, let us kill him and seize his inheritance." The parable was so transparent that the leaders knew it was about them.','Jesus left no ambiguity: the Father sent His Son, and the tenants (Israel\'s leaders) would reject and kill Him, just as the parable described.'), tf('The chief priests and Pharisees wanted to arrest Jesus immediately after the parable but restrained themselves because they feared the multitude.',0,'Matthew 21:46 — they sought to seize Him but feared a riot. The crowd was the only restraint on leaders who had already decided to kill Him.','Their restraint was not moral — it was tactical. They would find a way, at a time and place without the crowd\'s protection.') ],

'ch-60': [ mc('Jesus accused the Pharisees of being like whitewashed tombs — what did He mean by this vivid comparison?',['That they were as cold and silent as the dead','That they appeared beautiful outwardly while inwardly being full of hypocrisy and wickedness','That their teaching was outdated and preserved only old traditions','That they were surrounded by death because their rituals involved animal sacrifice'],1,'Matthew 23:27 — outward beauty, inward corruption. Whitewashing was done at Passover to warn travelers. A dazzling exterior covered what was deadly inside.','Ellen White calls this the most devastating exposure of religious hypocrisy in all of Scripture — beauty used to conceal, not to express, the heart.'), tf('Jesus said the Pharisees carefully tithed even the smallest herbs like mint, dill, and cumin while neglecting justice, mercy, and faithfulness.',0,'Matthew 23:23 — He did not say they should stop tithing the herbs; He said they should have done both without neglecting the weightier matters.','Precise religious observance is not wrong, but when it becomes a substitute for love and justice, it becomes the worst form of self-deception.') ],

'ch-61': [ mc('When the disciples admired the beautiful temple buildings, Jesus shocked them by predicting:',['God would fill the temple with an even greater glory than Solomon\'s day','Roman armies would besiege Jerusalem within that very generation','Not one stone of the temple would be left on another — it would be completely thrown down','The temple would be purified and become the center of the coming kingdom'],2,'Matthew 24:2 — this prediction was fulfilled in AD 70 when Titus destroyed Jerusalem. Jesus was not speaking symbolically.','Ellen White connects the destruction of Jerusalem directly to the rejection of Christ — the temple that rejected its Messiah could not stand.'), tf('In the Olivet Discourse, Jesus warned His followers that when they see Jerusalem surrounded by armies, they should immediately stand and defend the city.',1,'He told them to flee to the mountains immediately. Their escape while the armies momentarily withdrew in AD 70 saved the entire Christian community in Jerusalem.','Ellen White emphasizes that the Christians who heeded Jesus\' warning escaped the catastrophe; those who stayed — trusting the city — perished.') ],

'ch-62': [ mc('Jesus said that no one knows the day or hour of His return except:',['The archangel Michael who will sound the trump','The sealed book of Daniel which will be opened at the end','The Father alone — not even the angels in heaven or the Son in His human capacity','The twenty-four elders who stand before God\'s throne'],2,'Matthew 24:36 — Father alone. This settles every date-setting attempt. The fact that no one knows the day intensifies rather than removes the urgency of readiness.','Ellen White cautions strongly against date-setting: if God withheld this knowledge even from the Son in His human state, it is not ours to discover.'), tf('Jesus compared the conditions at His Second Coming to the days of Noah — people fully absorbed in ordinary life, unaware, until the moment of crisis.',0,'Matthew 24:37-39 — eating, drinking, marrying, building — not necessarily sinful, but absorbed in the earthly to the exclusion of spiritual readiness.','The danger is not moral depravity alone but spiritual inattention. Ordinary life, pursued without reference to God, produces the same unreadiness.') ],

'ch-63': [ mc('In the Parable of the Ten Virgins, what does the extra oil carried by the five wise virgins represent?',['Financial preparation for the long wait for Christ\'s return','A genuine personal relationship with Christ — an inner grace that cannot be borrowed at the last moment','The extra good works stored up by faithful churchgoers over their lifetime','Literal oil for use in formal worship services'],1,'The oil represents the Holy Spirit and the character formed by a living relationship with Christ — something that cannot be received secondhand.','Ellen White is emphatic: the oil cannot be transferred. No one can borrow another person\'s faith or relationship with God at the last moment.'), tf('When the five foolish virgins asked the five wise virgins for oil, the wise ones generously shared enough to light all ten lamps for the bridegroom.',1,'Matthew 25:9 — "there will not be enough for us and you." It was not selfishness but impossibility. Character cannot be shared or transferred.','They told the foolish to go buy for themselves. But when they returned, the door was shut — "I do not know you." Late preparation was no preparation.') ],

'ch-64': [ mc('When Mary poured expensive ointment on Jesus at Bethany and Judas objected it was wasteful, Jesus said Mary had done something beautiful. What was its deeper significance?',['It was the correct way to honor a visiting rabbi according to tradition','She had anointed His body for burial — an unconscious act of prophetic significance','It was a demonstration for the disciples of generous, impulsive giving','The perfume\'s value made it an appropriate gift for the Son of God'],1,'Jesus connected Mary\'s act of love to His coming death. She may not have fully understood, but the Spirit moved her at the exact right moment.','Ellen White writes that this act of devotion would be memorialized wherever the gospel is preached — Christ honored it above all the religious activity of that week.'), tf('It was directly after Jesus\' rebuke of Judas for his criticism of Mary\'s anointing that Judas went to betray Jesus for thirty pieces of silver.',0,'The rebuke was the final push. Wounded pride and love of money combined — Judas went immediately to the chief priests.','Ellen White identifies this moment as decisive for Judas. A heart that has made up its mind to betray will find any occasion as justification.') ],

'ch-65': [ mc('At the Last Supper, Jesus demonstrated the nature of leadership in His kingdom by performing what act that was culturally reserved for the lowest servant?',['Serving the bread and wine Himself to each disciple','Washing the disciples\' feet — including those of Judas','Praying over each disciple individually as a priestly act','Bowing before each disciple as an act of humility'],1,'John 13:5 — the Creator of the universe knelt before His creatures and washed feet. This was not a symbolic gesture — it was a literal act of radical humility.','Ellen White calls it the most powerful sermon ever preached: no words, just a basin of water and towel, redefining greatness entirely.'), tf('Peter refused to let Jesus wash his feet at all, standing firm in his refusal even after Jesus explained its significance.',1,'Peter first refused, then overreacted: "Lord, not my feet only, but also my hands and my head!" — from absolute refusal to excessive request.','Peter\'s all-or-nothing personality shows even here. Jesus graciously corrected both extremes: "One who has bathed needs only to wash his feet."') ],

'ch-66': [ mc('Ellen White teaches that the bread and wine of the communion service:',['Literally become the body and blood of Christ through the prayer of consecration','Are purely symbolic with no special spiritual significance — merely reminders of a historical event','Are a living memorial that keeps the sacrifice of Christ fresh before the believer\'s mind as the source of salvation','Are only effective if administered by an ordained clergyman in an official church setting'],2,'The Lord\'s Supper is a memorial and a proclamation — not bare symbol, not transubstantiation, but a living encounter with the truth of Christ\'s atoning sacrifice.','Ellen White writes that at every communion, Christ meets His people afresh. The ordinance is designed to keep the atonement central to Christian experience.'), tf('Jesus identified His betrayer at the Last Supper by handing him a piece of bread, identifying Judas specifically to the whole group of disciples.',1,'John 13:26 — only John seems to have understood the sign at the time. Judas left immediately, and the others did not know why.','The identification was subtle enough that most missed it. Ellen White shows Christ gave Judas every possible final opportunity to turn back.') ],

'ch-67': [ mc('Jesus promised to send the Holy Spirit, the Comforter, who would do which of the following for the disciples?',['Give them immunity from persecution and hardship','Visibly replace Jesus with a physical presence on earth','Guide them into all truth, bring Jesus\' words to remembrance, and be their Advocate','Reveal to them the exact year and events of the Second Coming'],2,'John 14:16-17, 26 — the Spirit continues Jesus\' presence and ministry, not replacing Him but making Him more universally present than His physical form allowed.','Ellen White writes that through the Spirit, Christ is closer to His disciples after the ascension than He could be in bodily presence.'), tf('Jesus said "I am the way, the truth, and the life; no one comes to the Father except through Me" in His farewell discourse.',0,'John 14:6 — one of the most exclusive and absolute statements in all of Scripture. No alternative path, no other truth, no other life source.','Ellen White treats this not as arrogance but as the most compassionate statement possible — if there is only one way, Christ is telling us exactly where it is.') ],

'ch-68': [ mc('In Gethsemane, what was the deepest source of Jesus\' agony that went beyond the fear of physical suffering?',['Uncertainty about whether the Father would actually raise Him after death','The weight of all human sin pressing upon Him and the sense of the Father\'s face being hidden from Him','Fear that the disciples would all permanently abandon Him','Doubt about whether His sacrifice would actually accomplish the salvation of humanity'],1,'Ellen White describes the cup as including the full weight of human guilt — separation from the Father, divine wrath against sin, the darkness of eternal death.','The physical suffering of crucifixion was nothing compared to this: the holy Son of God experiencing the hiding of the Father\'s face as He bore our sin.'), tf('Jesus prayed the same prayer three times in Gethsemane: "Not My will, but Yours be done," each time returning to find the disciples awake and praying with Him.',1,'Each time He returned they were asleep — three times the prayer, three times the return to sleeping disciples. He bore this alone.','Ellen White notes the profound loneliness of Gethsemane: in the moment of greatest need, those closest to Him could not stay awake even one hour.') ],

'ch-69': [ mc('When Judas approached Jesus in the garden and kissed Him as the signal for the soldiers, what did Jesus say to him?',['Nothing — He remained completely silent in fulfillment of Isaiah\'s prophecy','Judas, do you betray the Son of Man with a kiss?','Depart from Me — I never knew you','Friend, have you come at last? Do what you came to do'],1,'Luke 22:48 — even in the moment of betrayal, Jesus addressed him. Not a curse but a piercing question — a last appeal to conscience.','Ellen White shows that even here, Jesus was reaching for Judas. The kiss that meant betrayal was met with a word that offered one last chance.'), tf('During the arrest in Gethsemane, Peter cut off the ear of the high priest\'s servant, and Jesus healed the severed ear before allowing Himself to be taken.',0,'Luke 22:51 — "He touched his ear and healed him." Even in arrest, Christ performed an act of healing for one of those arresting Him.','Ellen White highlights this: in the worst moment of human injustice against Him, Christ\'s first act was a miracle of mercy on one of His captors.') ],

'ch-70': [ mc('When Caiaphas demanded under oath "Tell us whether you are the Christ, the Son of God!" Jesus replied:',['He remained completely silent, refusing to answer under false authority','You have said it. Nevertheless, I tell you: hereafter you will see the Son of Man coming on the clouds of heaven','I am not what you think — you misunderstand my teaching','Let my disciples answer for me'],1,'Matthew 26:64 — the silence was broken for the one question that mattered most. Jesus affirmed His identity and pointed to the future vindication of His claims.','This was the testimony that sealed His condemnation — a direct claim of divine identity and Messianic glory, delivered calmly and majestically.'), tf('Peter\'s three denials of Jesus happened exactly as Jesus had predicted, and after the third denial Peter went out and wept bitterly.',0,'Luke 22:61-62 — Jesus turned and looked at Peter. That look broke him. He went out and wept — not just regret, but the beginning of genuine repentance.','Ellen White distinguishes Peter\'s tears from Judas\'s remorse: Peter\'s grief led him back to Jesus; Judas\'s led him to despair and death.') ],

'ch-71': [ mc('When Judas returned the thirty pieces of silver to the chief priests and confessed "I have sinned by betraying innocent blood," they responded:',['By releasing Jesus since the betrayer himself admitted guilt','By accepting the money back and calling off the arrest warrant','By saying "What is that to us? See to it yourself!" and ignoring him','By offering to intercede for Judas with Pilate'],2,'Matthew 27:4 — the priests who hired him wanted no further association. When his usefulness was over, they abandoned him without a thought.','Judas was disposable to them. Those who use others for evil purposes have no loyalty — only utility. When the tool is no longer needed, it is discarded.'), tf('Judas\' remorse after betraying Jesus was genuine repentance that led him to seek God\'s forgiveness and restoration.',1,'Ellen White distinguishes sharply: Judas felt remorse (sorrow for consequences) but not repentance (sorrow that leads to God). He never sought mercy — only tried to undo what could not be undone.','He confessed to the priests, not to God. He returned the money, then despaired — the fruit of remorse without repentance is always destruction.') ],

'ch-72': [ mc('Three times Pilate declared Jesus innocent and tried to release Him. What finally forced Pilate to condemn the man he knew was innocent?',['The crowd threatened to riot and destroy the governor\'s residence','The chief priests said "If you release this man you are not Caesar\'s friend" — a threat to report him to Rome for disloyalty','A personal threat from Caiaphas to have him assassinated','The Roman soldiers refused to carry out a release order for a Jewish prisoner'],1,'John 19:12 — the threat of political accusation to Caesar was the lever that broke Pilate. His judgment was for sale to whoever held the most political pressure.','Pilate was a coward masquerading as an authority. Ellen White calls his handwashing one of history\'s greatest self-deceptions — you cannot wash away a verdict your hand just signed.'), tf('Pilate washed his hands before the crowd and declared himself innocent of Jesus\' blood, and the crowd responded "His blood be on us and on our children."',0,'Matthew 27:24-25 — one of the most sobering exchanges in Scripture. Pilate\'s gesture was meaningless; the crowd\'s words were weightier than they knew.','Ellen White treats this moment with deep solemnity — a nation pronouncing a verdict on itself, a choice whose consequences would unfold over the next forty years.') ],

'ch-73': [ mc('The inscription Pilate ordered placed on the cross above Jesus read, in three languages:',['Jesus of Galilee, Enemy of Caesar','Jesus of Nazareth, King of the Jews','Jesus the Nazarene, Convicted of Blasphemy','Jesus, Rebel and Deceiver of Israel'],1,'John 19:19-20 — written in Hebrew, Greek, and Latin so that every passerby could read it. Pilate refused to change it despite the priests\' protests.','The inscription was truer than Pilate intended. He wrote it to mock the Jews; God used it to proclaim the truth about who hung there.'), tf('As Jesus hung on the cross, He prayed "Father, forgive them, for they do not know what they do" — even for those crucifying Him.',0,'Luke 23:34 — intercession from the cross for those driving the nails. This is the love that baffles human understanding.','Ellen White writes that this prayer was the fulfillment of His own teaching to love enemies — lived out at the supreme cost.') ],

'ch-74': [ mc('When Jesus cried "It is finished!" and gave up His spirit, what was the full meaning of this declaration?',['That Jesus had accepted defeat and His mission had failed','That His physical suffering was over but His work in heaven was just beginning','That the plan of redemption was fully accomplished — the debt of sin paid completely on humanity\'s behalf','That the old covenant had ended and a new religious system would begin'],2,'John 19:30 — "Tetelestai" — a commercial term meaning "paid in full." The whole account of sin was settled; nothing remained to be added.','Ellen White calls this the most important word ever spoken — the cry of a Victor, not a victim. The work of salvation was complete.'), tf('At the moment of Jesus\' death, the temple veil was torn from top to bottom, the earth shook, rocks split, and many saints who had died were raised.',0,'Matthew 27:51-53 — a series of miraculous signs witnessed by all Jerusalem. Heaven itself marked the moment when the old order of sacrifice ended.','The torn veil was God\'s own declaration: the barrier between humanity and the Most Holy Place was removed by the death of the High Priest who was also the sacrifice.') ],

'ch-75': [ mc('On the Sabbath that Jesus lay in the tomb, what was the condition of His disciples?',['They were meeting in secret to plan how to protect the tomb from desecration','They were preparing anointing spices and trusting in the promised resurrection','They were hiding in grief and fear, having completely lost hope','They were going to Pilate to request an audience about the situation'],2,'The cross had shattered their expectations. They did not understand what they had been told about the resurrection — grief and confusion ruled that Sabbath.','Ellen White describes the disciples as utterly bereft. The Sabbath that should have been rest was a day of darkness they could barely endure.'), tf('Satan and the forces of evil celebrated through that Sabbath, believing they had achieved a permanent victory over the Son of God.',0,'Ellen White describes Satan\'s apparent triumph in Cosmic terms, then shows how completely he had misread the situation — what he thought was his greatest victory was his decisive defeat.','The powers of darkness did not understand what they had done — in killing the Lord of life, they had provided the very sacrifice that would destroy them.') ],

'ch-76': [ mc('Who was the first person to see the resurrected Jesus?',['Simon Peter, who ran to the tomb first','The angel who rolled away the stone','Mary Magdalene, who lingered at the empty tomb after the others left','The two disciples on the road to Emmaus'],2,'John 20:14-16 — Mary remained when others left. Her love kept her at the tomb; her tears kept her from immediately recognizing Him. He spoke her name and she knew.','The first person to receive the greatest news in history was a woman with a past of deep sin — itself a proclamation of the gospel\'s radical grace.'), tf('The Roman soldiers guarding the tomb were bribed by the chief priests to say that the disciples stole the body while they slept on duty.',0,'Matthew 28:12-13 — a lie that required confessing to sleeping on duty, itself a capital offense in the Roman army. They paid the price for a story they knew was false.','This desperate cover-up actually provides historical evidence for the resurrection: guards who were there could find no natural explanation either.') ],

'ch-77': [ mc('Why did the two disciples walking to Emmaus fail to recognize Jesus as He joined them and walked with them?',['It was dusk and too dim to see clearly','Jesus wore ordinary clothing designed to disguise Him','Their eyes were supernaturally restrained from recognizing Him until the right moment','They had never personally seen Jesus before and only knew Him by reputation'],2,'Luke 24:16 — "their eyes were restrained." This was a divine act. Christ walked with them, taught them Scripture, and waited for the appointed moment.','The timing of recognition was controlled. He revealed Himself in the breaking of bread — a deliberate echo of the Last Supper and every communion after.'), tf('The disciples said their hearts burned within them while Jesus explained the Scriptures to them on the road — they recognized the feeling even before recognizing the person.',0,'Luke 24:32 — "Were not our hearts burning within us?" The Spirit\'s witness was present before their eyes were opened. Truth ignites the heart before the mind catches up.','Ellen White writes that the burning heart is one of the signs of Christ\'s presence — we may not always see Him, but the heart that seeks Him will feel Him.') ],

'ch-78': [ mc('When Jesus appeared to the disciples (Thomas absent) behind locked doors, their initial response was:',['Immediate recognition and joyful worship','They thought He was a ghost — a spiritual apparition, not a physical presence','They accused Mary Magdalene of deceiving them','They were so overjoyed they could not speak or move'],1,'Luke 24:37 — "they were terrified and frightened, and supposed they had seen a spirit." The resurrection body was real and physical, yet unexpected.','The resurrection was not what they expected — they had given up hoping. The greatest news was hardest to receive precisely because it was so much better than they dared believe.'), tf('To prove He was physically real and not a spirit, Jesus invited them to touch His hands and feet and ate fish in their presence.',0,'Luke 24:39-43 — He showed them His hands and feet, invited touching, then ate broiled fish. The resurrection body is physical, recognizable, and capable of eating.','Ellen White emphasizes the physical resurrection against every spiritualizing tendency. Christ rose bodily — and so will His people.') ],

'ch-79': [ mc('When Jesus appeared to Thomas and Thomas saw Him, Thomas\'s immediate response was:',['Asking for additional proof beyond what he could see','Fainting from the shock of seeing someone he believed was dead','"My Lord and my God!" — the highest confession of divinity in the Gospels','A quiet personal acknowledgment that he now believed'],2,'John 20:28 — not "my teacher" or "my master" but "my Lord and my God." Thomas went from the greatest doubt to the greatest confession.','Ellen White notes the transformative power of encounter with the risen Christ — Thomas needed to see, and when he did, his response was total surrender.'), tf('Jesus gently rebuked Thomas by saying "Blessed are those who have not seen and yet have believed," suggesting Thomas\'s faith was second-rate.',0,'John 20:29 — Jesus did not dismiss Thomas\' faith but used this moment to pronounce a blessing on all future believers who would believe without physical sight.','Thomas believed what he saw; billions would believe without seeing. Both are real faith; the latter is commended as the normal pattern of Christian trust.') ],

'ch-80': [ mc('Jesus asked Peter "Do you love Me?" three times by the Sea of Tiberias. Ellen White explains this three-fold pattern was:',['A formal ordination ceremony establishing Peter as the head of the church','A test to see whether Peter\'s love was truly greater than the other disciples\'','A gentle restoration corresponding to Peter\'s three denials — recommissioning him for the ministry he had seemed to disqualify himself from','A ritual required before any disciple could be given pastoral responsibilities'],2,'Three denials, three questions, three affirmations. Christ was not rubbing Peter\'s nose in his failure — He was systematically restoring him.','Ellen White writes that Christ never uses our past failures as permanent disqualifiers. The restoration was as thorough as the fall had been complete.'), tf('The third time Jesus asked "Do you love Me?" Peter was grieved and appealed to Jesus\' omniscience: "Lord, You know all things; You know that I love You."',0,'John 21:17 — Peter stopped trying to argue his case and threw himself on Christ\'s perfect knowledge. It is the prayer of every honest heart that knows its own inconsistency.','Peter could no longer trust his own declarations of love — he had made them before and failed. Now he rested on Christ\'s knowledge of him rather than his knowledge of himself.') ],

'ch-81': [ mc('The Great Commission Jesus gave (Matthew 28:18-20) contains three active commands. Which of the following is the ONLY imperative verb in the original Greek?',['Go — travel to every nation immediately','Baptize — make baptism the central act of ministry','Teach — instruction is more important than going','Make disciples — going, baptizing, and teaching are all means to this one command'],3,'Technically, "make disciples" (mathēteusate) is the only imperative; "go," "baptize," and "teach" are participles describing how. The goal is disciple-making, not just evangelism.','Ellen White emphasizes that the mission is not merely decisions or baptisms but transformed followers — disciples who then make more disciples.'), tf('Jesus promised "Lo, I am with you always, even to the end of the age" as the closing guarantee of the Great Commission.',0,'Matthew 28:20 — the Commission ends not with an obligation but with a promise. Go — because I go with you. Make disciples — because I will be there.','Ellen White writes that this promise is the inexhaustible resource for every missionary endeavor. No one is ever sent alone.') ],

'ch-82': [ mc('Before His ascension, Jesus told the disciples to remain in Jerusalem and wait for what?',['The arrival of Paul who would guide the young movement','A sign from the sky that would tell them when to begin preaching','The promise of the Father — power from the Holy Spirit which would equip them to be His witnesses','Permission from the Roman government to preach freely'],2,'Acts 1:4-5, 8 — without the Spirit they were not equipped for the mission. Jesus was wiser than to send willing but unprepared messengers.','The disciples had courage, love, and three years of training — but without the Spirit\'s power they could not fulfill the Commission. The wait was not delay but preparation.'), tf('Jesus ascended visibly into heaven while the disciples watched, and a cloud received Him out of their sight.',0,'Acts 1:9 — the cloud of the Shekinah glory received Him. Two angels appeared and promised He would return in the same way He departed.','Ellen White describes the ascension as a royal procession — the returning Victor entering heaven with the trophies of His completed mission.') ],

'ch-83': [ mc('The ascension of Jesus to the Father\'s right hand means that right now Jesus serves as:',['A passive observer of earthly affairs, waiting until the Second Coming','Our High Priest and Advocate before the Father, interceding for every believer in the Most Holy Place','A symbolic figure whose presence is only felt through the Scriptures','The executive administrator directing angels without personal involvement in individual lives'],1,'Hebrews 8:1, 1 John 2:1 — He is actively interceding at this moment. The ascended Christ is not idle but is pleading His own merits for each of His people.','Ellen White writes that Christ\'s ministry in the heavenly sanctuary is just as real and just as essential as His ministry on earth. Salvation has both an earthly and a heavenly dimension.'), tf('The disciples returned to Jerusalem from the Mount of Olives after the ascension with sorrow and mourning, feeling abandoned and uncertain of the future.',1,'Luke 24:52 — "they returned to Jerusalem with great joy." The ascension was not abandonment; they understood it as the next phase of Christ\'s exaltation.','They had seen Him go in triumph. They knew He was alive, exalted, interceding — and had promised to return. Joy, not grief, marked their return.') ],

'ch-84': [ mc('The gift of the Holy Spirit at Pentecost was the fulfillment of Christ\'s promise and represented:',['The final completion of Christ\'s work — nothing more remained to be done in heaven or earth','Christ\'s own presence coming to dwell within His people in a new and universal way through the Spirit','A temporary gift for the apostolic age only, not promised to subsequent generations','God\'s sign of approval for the disciples\' decision to gather together in the upper room'],1,'John 14:18 — "I will not leave you orphans; I will come to you." The Spirit is the presence of Christ universalized — no longer limited to one body in one place.','Ellen White teaches that the gift of the Spirit was Christ\'s most precious bequest to His church — His own presence made accessible to every believer everywhere.'), tf('The disciples were equipped for their mission not by superior education, eloquence, or social standing but by the power of the Holy Spirit.',0,'Acts 4:13 — authorities "recognized that they had been with Jesus." Unlettered fishermen confounded the educated elite — the Spirit\'s power made the difference.','Ellen White writes that the church\'s greatest need in every age is not better strategies or more resources but the fullness of the Holy Spirit.') ],

'ch-85': [ mc('Ellen White summarizes Christ\'s entire ministry in "The Desire of Ages" as ultimately being about:',['Establishing the correct form of church government for the Christian community','Revealing the Father\'s character as one of boundless love and selfless service, and restoring that image in humanity','Defeating Roman political oppression through spiritual means','Creating a new religious system to replace the corrupted Judaism of the first century'],1,'The life of Christ is the supreme revelation of God\'s character — everything He did showed us what God is like and what He wants us to become.','Ellen White\'s central thesis: the plan of salvation is not primarily legal transaction but character restoration — God making us like Himself through Christ.'), tf('The study of Christ\'s life is the most important study we can engage in, because knowing Him personally is eternal life itself.',0,'John 17:3 — "This is eternal life: that they may know You, the only true God, and Jesus Christ whom You have sent."','Ellen White opens and closes "The Desire of Ages" with this conviction: knowing Christ — not knowing about Him — is itself the substance of eternal life.') ],

'ch-86': [ mc('What does Ellen White call "the science of salvation" that all heaven will study throughout eternity?',['The detailed chronology of prophecy and its fulfillment in history','The cross of Christ — the character of God fully revealed in the self-sacrifice of the Son','The structure of the heavenly sanctuary and its earthly counterpart in the tabernacle','The progressive unfolding of the plan of salvation through the covenants'],1,'The cross is inexhaustible — angels will study it forever. Its depths of love and wisdom can never be fully plumbed in time or eternity.','Ellen White writes that the cross is the central truth of the universe — the point where God\'s justice and mercy, His power and His love, are most perfectly displayed.'), tf('Ellen White teaches that the character of God as revealed in Christ\'s life completely refutes Satan\'s accusations that God is selfish, harsh, and unworthy of loyalty.',0,'The entire great controversy is resolved at the cross: God proved His character by dying for His enemies. No accusation can stand against that evidence.','The vindication of God\'s character was the ultimate purpose of the incarnation — showing the universe what God is truly like.') ],

'ch-87': [ mc('The final chapters of "The Desire of Ages" point forward to what great event that gives all of Christ\'s life and work its ultimate meaning?',['The establishment of the Christian church as a permanent institution on earth','The complete spread of the gospel to every nation, fulfilled within one generation of the apostles','The Second Coming of Christ in glory, when all the redeemed will see Him face to face','The final translation of all the writings of the apostles into every known language'],2,'The entire ministry of Christ — His incarnation, teaching, death, resurrection, and ascension — points to the moment when He returns to take His people home.','Ellen White closes "The Desire of Ages" with the forward look: the same Jesus who walked in Galilee is coming again. This hope anchors every believer.'), tf('Ellen White teaches that understanding Christ\'s first coming deepens rather than reduces our longing for His second coming.',0,'The more clearly we see who came the first time, the more passionately we desire to see Him come again in glory — knowledge of Christ always intensifies the Advent hope.','"The Desire of Ages" is titled for this: the deepest desire of every age is Christ Himself — and He is coming. This is the note on which the book ends.') ],
};

// ── Chapter metadata ──────────────────────────────────────────────────────────

const CHAPTERS = [];
for (let n = 3; n <= 87; n++) {
  CHAPTERS.push({ n, id: 'ch-' + n });
}

// ── Scraper ───────────────────────────────────────────────────────────────────

async function fetchTOC() {
  console.log('Fetching table of contents…');
  try {
    const html = await get('https://m.egwwritings.org/en/book/130/toc');
    const map = {};
    // Match href AND capture text in same anchor: href="/en/book/130.NNN">Chapter N—Title
    const re = /href="(\/en\/book\/130\.(\d+))"[^>]*>([^<]+)/gi;
    let m;
    while ((m = re.exec(html)) !== null) {
      const text = m[3].trim();
      const chMatch = text.match(/Chapter\s+(\d+)/i);
      if (chMatch) {
        map[parseInt(chMatch[1])] = 'https://m.egwwritings.org' + m[1];
      }
    }
    if (Object.keys(map).length > 80) {
      console.log(`TOC parsed — found ${Object.keys(map).length} chapter links.`);
      return map;
    }
    console.warn('TOC parse yielded fewer chapters than expected:', Object.keys(map).length);
  } catch(e) {
    console.warn('TOC fetch failed:', e.message);
  }
  return {};
}

async function fetchChapterText(url) {
  const html = await get(url);
  const paras = extractParagraphs(html);
  if (paras.length === 0) return { content: '', content2: '' };
  const mid = Math.ceil(paras.length / 2);
  const content  = paras.slice(0, mid).join('\n\n');
  const content2 = paras.slice(mid).join('\n\n');
  return { content, content2 };
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  const tocMap = await fetchTOC();
  const allQuizzes = Object.assign({}, QUIZZES, QUIZZES2);
  let ok = 0, fail = 0;

  for (const ch of CHAPTERS) {
    const chId  = ch.id;
    const quiz  = allQuizzes[chId] || [];
    let textData = { content: '', content2: '' };

    const url = tocMap[ch.n];
    if (url) {
      try {
        textData = await fetchChapterText(url);
        await sleep(DELAY_MS);
      } catch(e) {
        console.warn(`  ⚠ Chapter ${ch.n} scrape failed: ${e.message}`);
      }
    } else {
      console.warn(`  ⚠ Chapter ${ch.n}: no URL in TOC map — uploading quiz only`);
    }

    const payload = {
      content:  textData.content,
      content2: textData.content2,
      images:   [],
      quiz,
    };

    try {
      await upload(chId, payload);
      ok++;
      const status = textData.content ? '✓' : '⚬';
      console.log(`${status} ch-${ch.n} uploaded (${quiz.length} quiz, ${textData.content ? 'content scraped' : 'no content'})`);
    } catch(e) {
      fail++;
      console.error(`✗ ch-${ch.n} upload failed: ${e.message}`);
    }

    await sleep(300);
  }

  console.log(`\nDone — ${ok} uploaded, ${fail} failed.`);
  if (fail > 0) {
    console.log('If uploads failed with 403, your Firestore rules may require authentication.');
    console.log('In Firebase Console → Firestore → Rules, temporarily set:');
    console.log('  allow read, write: if true;');
    console.log('Then re-run this script, then restore your rules.');
  }
}

main().catch(console.error);
